// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz a dummy uint to satisfy requirement of at least one parameter; the property is independent
    function testFuzz_property(uint256 junk) public {
        // Keep junk unconstrained; it does not affect C.version() but satisfies fuzzer input requirement

        // Call version and check it contains exactly two '.' characters (three components)
        string memory v = c.version();

        bytes memory b = bytes(v);
        uint256 dotCount = 0;
        for (uint256 i = 0; i < b.length; i++) {
            if (b[i] == byte('.')) {
                dotCount++;
            }
        }

        // Reference contract always returns a three-component semver (two dots); the mutant "1.0" has only one dot
        assertTrue(dotCount == 2);
    }
}

contract InvMutTest {
    C public c;

    constructor(C _c) { c = _c; }

    // single entry that performs the distinguishing call
    function run(address caller, uint64 _number, uint64 _timestamp, uint256 _basefee, bytes32 _hash, uint64 _sequenceNumber, bytes32 _batcherHash, uint256 _l1FeeOverhead, uint256 _l1FeeScalar) public {
        // require that `caller` is not the zero address to avoid ambiguity
        require(caller != address(0));

        // Attempt to call setL1BlockValues as `caller` by using a low-level call.
        // We encode the calldata for the external function and call c with that sender.
        // The effects we can observe from c are whether the call succeeded (did not revert).

        bytes memory data = abi.encodeWithSignature(
            "setL1BlockValues(uint64,uint64,uint256,bytes32,uint64,bytes32,uint256,uint256)",
            _number,
            _timestamp,
            _basefee,
            _hash,
            _sequenceNumber,
            _batcherHash,
            _l1FeeOverhead,
            _l1FeeScalar
        );

        // Perform the call: simulate `caller` by using address(this) but require that
        // the externally provided `caller` equals address(this) so the call's sender is controlled.
        // This keeps the test within the single-contract constraint: we cannot change msg.sender,
        // so require the provided caller to match this contract's address to represent that identity.
        require(caller == address(this), "caller must equal this contract for msg.sender control");

        // Now perform the state-changing call on c; its success boolean distinguishes P vs M.
        (bool ok, ) = address(c).call(data);

        // On the original contract P, only the depositor account (DEPOSITOR_ACCOUNT) may call,
        // so for any caller that is not that depositor, the call must revert (ok == false).
        // Our general rule: for arbitrary inputs and caller != depositor, the attempt to call
        // setL1BlockValues must fail. We express this by asserting that if caller is not equal
        // to c.depositorAccount() then ok is false.

        // Read depositorAccount via its public getter
        address depo = c.depositorAccount();

        assert( (caller == depo) || (!ok) );
    }

    // allow receiving ETH (not used, but permitted)
    receive() external payable {}
}

